import os
from typing import Any, Dict, List, Optional

import boto3


class TextractTableExtractor:
    def __init__(
        self,
        region_name: Optional[str] = None,
        aws_access_key_id: Optional[str] = None,
        aws_secret_access_key: Optional[str] = None,
        aws_session_token: Optional[str] = None,
    ) -> None:
        self.client = boto3.client(
            "textract",
            region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1",
            aws_access_key_id=aws_access_key_id or os.getenv("AWS_ACCESS_KEY_ID"),
            aws_secret_access_key=aws_secret_access_key or os.getenv("AWS_SECRET_ACCESS_KEY"),
            aws_session_token=aws_session_token or os.getenv("AWS_SESSION_TOKEN"),
        )

    def extract_tables_from_bytes(self, document_bytes: bytes) -> List[Dict[str, Any]]:
        response = self.client.analyze_document(
            Document={"Bytes": document_bytes},
            FeatureTypes=["TABLES"],
        )
        return self._parse_tables(response.get("Blocks", []))

    def extract_tables_from_s3(self, bucket: str, name: str, version: Optional[str] = None) -> List[Dict[str, Any]]:
        document_location: Dict[str, Any] = {"S3Object": {"Bucket": bucket, "Name": name}}
        if version:
            document_location["S3Object"]["Version"] = version

        response = self.client.analyze_document(
            Document=document_location,
            FeatureTypes=["TABLES"],
        )
        return self._parse_tables(response.get("Blocks", []))

    def _parse_tables(self, blocks: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        block_map = {block["Id"]: block for block in blocks if "Id" in block}
        tables: List[Dict[str, Any]] = []

        for block in blocks:
            if block.get("BlockType") != "TABLE":
                continue

            table_cells = self._collect_table_cells(block, block_map)
            max_row = max((cell["row_index"] for cell in table_cells), default=0)
            rows: List[Dict[str, Any]] = []

            for row_index in range(1, max_row + 1):
                row_cells = [c for c in table_cells if c["row_index"] == row_index]
                row_cells.sort(key=lambda c: c["column_index"])
                rows.append(
                    {
                        "row_index": row_index,
                        "cells": row_cells,
                        "text": [c["text"] for c in row_cells],
                    }
                )

            tables.append(
                {
                    "table_id": block["Id"],
                    "page": block.get("Page"),
                    "confidence": block.get("Confidence"),
                    "bounding_box": self._get_bounding_box(block),
                    "row_count": max_row,
                    "column_count": max((cell["column_index"] + cell["column_span"] - 1 for cell in table_cells), default=0),
                    "rows": rows,
                    "cells": table_cells,
                }
            )

        return tables

    def _collect_table_cells(self, table_block: Dict[str, Any], block_map: Dict[str, Dict[str, Any]]) -> List[Dict[str, Any]]:
        cells: List[Dict[str, Any]] = []

        for rel in table_block.get("Relationships", []):
            if rel.get("Type") != "CHILD":
                continue

            for child_id in rel.get("Ids", []):
                child = block_map.get(child_id)
                if not child or child.get("BlockType") != "CELL":
                    continue

                cells.append(
                    {
                        "cell_id": child["Id"],
                        "row_index": child.get("RowIndex", 0),
                        "column_index": child.get("ColumnIndex", 0),
                        "row_span": child.get("RowSpan", 1),
                        "column_span": child.get("ColumnSpan", 1),
                        "text": self._extract_cell_text(child, block_map),
                        "confidence": child.get("Confidence"),
                        "bounding_box": self._get_bounding_box(child),
                        "entity_types": child.get("EntityTypes", []),
                    }
                )

        cells.sort(key=lambda c: (c["row_index"], c["column_index"]))
        return cells

    def _extract_cell_text(self, cell_block: Dict[str, Any], block_map: Dict[str, Dict[str, Any]]) -> str:
        parts: List[str] = []

        for rel in cell_block.get("Relationships", []):
            if rel.get("Type") != "CHILD":
                continue

            for child_id in rel.get("Ids", []):
                child = block_map.get(child_id)
                if not child:
                    continue

                block_type = child.get("BlockType")
                if block_type == "WORD":
                    parts.append(child.get("Text", ""))
                elif block_type == "SELECTION_ELEMENT" and child.get("SelectionStatus") == "SELECTED":
                    parts.append("X")

        return " ".join(part for part in parts if part)

    def _get_bounding_box(self, block: Dict[str, Any]) -> Optional[Dict[str, float]]:
        geometry = block.get("Geometry", {})
        bbox = geometry.get("BoundingBox")
        if not bbox:
            return None
        return {
            "left": bbox.get("Left", 0.0),
            "top": bbox.get("Top", 0.0),
            "width": bbox.get("Width", 0.0),
            "height": bbox.get("Height", 0.0),
        }
